enum Wave { Sine, Square, Saw, Tri }

fn wave_of(n: i32) -> Wave {
    if n == 0 {
        Wave::Sine
    } else {
        if n == 1 {
            Wave::Square
        } else {
            if n == 2 { Wave::Saw } else { Wave::Tri }
        }
    }
}

fn code(w: Wave) -> i32 {
    match w {
        Wave::Sine => 0,
        Wave::Square => 1,
        Wave::Saw => 2,
        Wave::Tri => 3,
    }
}

fn frame(t: i32) {
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    let mut sel: i32 = host::display::state_get(1);
    if down == 1 && prev == 0 {
        sel = (sel + 1) % 4;
        host::audio::tone(440, 250, code(wave_of(sel)));
    }
    host::display::state_set(0, down);
    host::display::state_set(1, sel);
    host::display::clear(0x101010);
    match sel {
        0 => {
            host::display::draw_string(20, 30, "SINE", 0xffffff, 3);
        }
        1 => {
            host::display::draw_string(20, 30, "SQUARE", 0xffffff, 3);
        }
        2 => {
            host::display::draw_string(20, 30, "SAWTOOTH", 0xffffff, 3);
        }
        _ => {
            host::display::draw_string(20, 30, "TRIANGLE", 0xffffff, 3);
        }
    }
    host::display::draw_string(20, 70, "TAP TO CYCLE + PLAY A440", 0x808080, 1);
    host::display::draw_number(20, 90, code(wave_of(sel)), 0x00ff00, 2);
    host::display::present();
}
